int main() {
    std::ifstream in("piepie.in");std::ofstream out("piepie.out");int n;long long d;in >> n >> d;
    std::vector<std::pair<long long,long long>> pie(2*n);for(auto& p:pie) in >> p.first >> p.second;
    std::vector<int> distance(2*n,-1);std::queue<int> pending;
    std::set<std::pair<long long,int>> remainingB,remainingE;
    for(int i=0;i<2*n;++i) {
        long long receiver=(i<n?pie[i].second:pie[i].first);
        if(receiver==0){distance[i]=1;pending.push(i);}
        else if(i<n) remainingB.insert({pie[i].second,i});
        else remainingE.insert({pie[i].first,i});
    }
    while(!pending.empty()) {
        int node=pending.front();pending.pop();bool fromB=node<n;
        long long current=fromB?pie[node].first:pie[node].second;
        auto& predecessors=fromB?remainingE:remainingB;
        auto it=predecessors.lower_bound({current-d,-1});
        while(it!=predecessors.end() && it->first<=current) {
            int previous=it->second;distance[previous]=distance[node]+1;pending.push(previous);it=predecessors.erase(it);
        }
    }
    for(int i=0;i<n;++i) out << distance[i] << '\n';
}
