#include <array>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("barnpainting.in");std::ofstream out("barnpainting.out");int n,k;in >> n >> k;
    std::vector<std::vector<int>> edges(n);for(int i=0;i<n-1;++i){int u,v;in >> u >> v;--u;--v;edges[u].push_back(v);edges[v].push_back(u);}
    std::vector<int> fixed(n,-1);bool conflict=false;
    for(int i=0;i<k;++i){int barn,color;in >> barn >> color;--barn;--color;if(fixed[barn]!=-1 && fixed[barn]!=color) conflict=true;fixed[barn]=color;}
    if(conflict){out << 0 << '\n';return 0;}
    std::vector<int> parent(n,-1),order{0};parent[0]=0;
    for(std::size_t i=0;i<order.size();++i){int u=order[i];for(int v:edges[u]) if(v!=parent[u]){parent[v]=u;order.push_back(v);}}
    constexpr long long mod=1000000007;
    std::vector<std::array<long long,3>> dp(n,{0,0,0});
    for(auto it=order.rbegin();it!=order.rend();++it) {
        int u=*it;
        for(int color=0;color<3;++color) {
            if(fixed[u]!=-1 && fixed[u]!=color) continue;
            long long ways=1;
            for(int v:edges[u]) if(parent[v]==u){long long options=(dp[v][(color+1)%3]+dp[v][(color+2)%3])%mod;ways=ways*options%mod;}
            dp[u][color]=ways;
        }
    }
    out << (dp[0][0]+dp[0][1]+dp[0][2])%mod << '\n';
}
