    std::vector<std::pair<long long,long long>> bale(n);for(auto& p:bale) in >> p.first >> p.second;
    long long sum=0,answer=std::numeric_limits<long long>::max();int left=0;std::deque<int> maximum;
    for(int right=0;right<n;++right) {
        sum+=bale[right].first;
        while(!maximum.empty() && bale[maximum.back()].second<=bale[right].second) maximum.pop_back();maximum.push_back(right);
        while(sum>=minimum) {
            answer=std::min(answer,bale[maximum.front()].second);
            sum-=bale[left].first;if(maximum.front()==left) maximum.pop_front();++left;
        }
    }
